<template>
  <div><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div>
    <TeacherClassSelector v-if="canManage && !selectedClassId" :classes="classes" :loading="loading" title="Bài tập & Bài thi" description="Chọn một lớp để xem, tạo và phát hành hoạt động." feature-count-label="hoạt động" @select="selectClass" />
    <template v-else>
    <section v-if="showForm" class="panel" style="margin-bottom:16px"><form class="grid-two" @submit.prevent="create"><div class="form-field"><label>Tiêu đề</label><input v-model.trim="form.title" class="form-input" required placeholder="Bài kiểm tra tuần 1" /></div><div class="form-field"><label>Loại</label><select v-model="form.kind" class="form-select"><option value="Assignment">Bài tập</option><option value="Exercise">Bài luyện tập</option><option value="Quiz">Bài trắc nghiệm</option><option value="Exam">Bài thi</option></select></div><div class="form-field"><label>Mô tả</label><input v-model.trim="form.description" class="form-input" placeholder="Mô tả hoạt động" /></div><div class="form-field"><label>Mở lúc</label><input v-model="form.opensAt" class="form-input" type="datetime-local" /></div><div class="form-field"><label>Hạn nộp</label><input v-model="form.dueAt" class="form-input" type="datetime-local" /></div><div v-if="form.kind === 'Exam'" class="form-field"><label>Thời lượng (phút)</label><input v-model.number="form.timeLimitMinutes" class="form-input" type="number" min="1" /></div><div v-if="form.kind === 'Exam'" class="form-field"><label>Số lần làm tối đa</label><input v-model.number="form.attemptLimit" class="form-input" type="number" min="1" /></div><div v-if="form.kind === 'Exam'" class="form-field"><label>Điểm đạt (%)</label><input v-model.number="form.passingScore" class="form-input" type="number" min="0" max="100" step="0.1" placeholder="Không bắt buộc" /></div><div v-if="form.kind === 'Exam'" class="form-field"><label>Thời điểm công bố kết quả</label><input v-model="form.resultsReleaseAt" class="form-input" type="datetime-local" /></div><label v-if="form.kind === 'Exam'" class="check-field"><input v-model="form.shuffleQuestions" type="checkbox" /> Xáo trộn câu hỏi</label><button class="button primary" :disabled="busy">Lưu hoạt động</button></form></section>
    <div class="toolbar page-toolbar"><div v-if="canManage" class="class-context"><strong>{{ selectedClassLabel }}</strong><button class="mini-button" @click="changeClass">Đổi lớp</button></div><select v-else v-model="selectedClassId" class="form-select" style="max-width:320px"><option value="">Tất cả lớp học</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select><div class="toolbar-actions"><span class="cell-subtle">{{ activities.length }} hoạt động</span><button v-if="canManage" class="button primary" @click="showForm = !showForm">{{ showForm ? 'Đóng biểu mẫu' : 'Tạo hoạt động' }}</button></div></div>
    <div v-if="loading" class="loading-state">Đang tải hoạt động…</div><div v-else-if="activities.length" class="cards-grid"><article v-for="item in activities" :key="item.id" class="activity-card"><div class="card-topline"><span class="code-label">{{ className(item.learningClassId) }}</span><StatusPill :value="item.status" :labels="enumLabels.activityStatus" /></div><h3>{{ item.title }}</h3><p>{{ item.description || `${enumLabel(item.kind, enumLabels.activityKind)} trong lớp học` }}</p><div class="card-footer"><span class="card-meta">{{ item.dueAt ? `Hạn ${formatDate(item.dueAt)}` : 'Không có hạn' }} · {{ item.questions.length }} câu hỏi</span><div class="card-actions"><RouterLink class="mini-button" :to="`/activities/${item.id}`">Mở không gian làm bài</RouterLink><button v-if="canManage && isDraft(item)" class="mini-button" :disabled="!item.questions.length" :title="item.questions.length ? 'Phát hành hoạt động' : 'Thêm ít nhất một câu hỏi trong không gian làm bài trước khi phát hành'" @click="publish(item.id)">Phát hành</button><button v-if="canManage && isPublished(item)" class="mini-button" @click="pause(item.id)">Tạm dừng</button><button v-if="canManage && isPaused(item)" class="mini-button" @click="resume(item.id)">Tiếp tục</button><button v-if="canManage && (isPublished(item) || isPaused(item))" class="mini-button" @click="close(item.id)">Đóng</button></div></div></article></div><div v-else class="panel empty-state"><strong>Chưa có hoạt động</strong><span>Hoạt động được phát hành cho lớp sẽ xuất hiện tại đây.</span></div>
    </template>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'; import { useRoute } from 'vue-router'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import TeacherClassSelector from '../../../shared/ui/TeacherClassSelector.vue'; import { academicsApi, assessmentApi } from '../../../shared/api/client'; import { errorMessage } from '../../../shared/api/http'; import { enumLabels, enumLabel, formatDate, type AssessmentActivity, type Course, type LearningClass } from '../../../shared/types'; import { useAuthStore } from '../../../shared/stores/auth'
const auth = useAuthStore(); const route = useRoute(); const classes = ref<LearningClass[]>([]); const courses = ref<Course[]>([]); const activities = ref<AssessmentActivity[]>([]); const selectedClassId = ref(typeof route.query.classId === 'string' ? route.query.classId : ''); const loading = ref(true); const busy = ref(false); const error = ref(''); const showForm = ref(false); const canManage = computed(() => auth.has('assessment.activities.manage')); const form = reactive({ classId: selectedClassId.value, title: '', description: '', kind: 'Assignment', opensAt: '', dueAt: '', timeLimitMinutes: 0, attemptLimit: 1, passingScore: undefined as number | undefined, resultsReleaseAt: '', shuffleQuestions: false })
const classNames = computed(() => new Map(classes.value.map(item => [item.id, `${item.code} · ${item.name}`]))); const selectedClassLabel = computed(() => classNames.value.get(selectedClassId.value) || 'Lớp học'); function selectClass(id: string) { selectedClassId.value = id }; function changeClass() { selectedClassId.value = '' }; function className(id: string) { return classNames.value.get(id) || 'Lớp học' }; function isDraft(item: AssessmentActivity) { return item.status === 0 || String(item.status).toLowerCase() === 'draft' }; function isPublished(item: AssessmentActivity) { return item.status === 1 || String(item.status).toLowerCase() === 'published' }; function isPaused(item: AssessmentActivity) { return item.status === 2 || String(item.status).toLowerCase() === 'paused' }; function isClosed(item: AssessmentActivity) { return item.status === 3 || String(item.status).toLowerCase() === 'closed' }
async function load() { loading.value = true; error.value = ''; try { classes.value = await academicsApi.classes(); const target = selectedClassId.value ? classes.value.filter(item => item.id === selectedClassId.value) : classes.value; const results = await Promise.allSettled(target.map(item => assessmentApi.activities(item.id))); activities.value = results.flatMap(result => result.status === 'fulfilled' ? result.value : []); if (!target.length) activities.value = [] } catch (cause) { error.value = errorMessage(cause) || 'Không tải được hoạt động.' } finally { loading.value = false } }
async function create() { busy.value = true; try { const exam = form.kind === 'Exam'; const totalSeconds = Math.max(0, form.timeLimitMinutes * 60); const hours = String(Math.floor(totalSeconds / 3600)).padStart(2, '0'); const minutes = String(Math.floor(totalSeconds % 3600 / 60)).padStart(2, '0'); const seconds = String(totalSeconds % 60).padStart(2, '0'); const created = await assessmentApi.createActivity(form.classId, { title: form.title, description: form.description, kind: form.kind, opensAt: form.opensAt ? new Date(form.opensAt).toISOString() : null, dueAt: form.dueAt ? new Date(form.dueAt).toISOString() : null, timeLimit: exam && form.timeLimitMinutes ? `${hours}:${minutes}:${seconds}` : null, examPolicy: exam ? { attemptLimit: form.attemptLimit, allowRetake: form.attemptLimit > 1, shuffleQuestions: form.shuffleQuestions, passingScore: form.passingScore, resultsReleaseAt: form.resultsReleaseAt ? new Date(form.resultsReleaseAt).toISOString() : null } : null }); activities.value.unshift(created); showForm.value = false; form.title = ''; form.description = ''; form.opensAt = ''; form.dueAt = ''; form.timeLimitMinutes = 0; form.attemptLimit = 1; form.passingScore = undefined; form.resultsReleaseAt = ''; form.shuffleQuestions = false } catch (cause) { error.value = errorMessage(cause) || 'Không tạo được hoạt động.' } finally { busy.value = false } }
async function publish(id: string) {
  const activity = activities.value.find(item => item.id === id)
  if (!activity) return
  if (!activity.questions.length) {
    error.value = 'Hoạt động cần ít nhất một câu hỏi. Mở không gian làm bài để thêm câu hỏi trước khi phát hành.'
    return
  }
  try {
    const updated = await assessmentApi.publishActivity(id)
    const index = activities.value.findIndex(item => item.id === id)
    if (index >= 0) activities.value[index] = updated
  } catch (cause) {
    error.value = errorMessage(cause) || 'Không phát hành được hoạt động.'
  }
}
async function pause(id: string) { try { const updated = await assessmentApi.pauseActivity(id); const index = activities.value.findIndex(item => item.id === id); if (index >= 0) activities.value[index] = updated } catch (cause) { error.value = errorMessage(cause) || 'Không tạm dừng được hoạt động.' } }
async function resume(id: string) { try { const updated = await assessmentApi.resumeActivity(id); const index = activities.value.findIndex(item => item.id === id); if (index >= 0) activities.value[index] = updated } catch (cause) { error.value = errorMessage(cause) || 'Không tiếp tục được hoạt động.' } }
async function close(id: string) { if (!window.confirm('Đóng hoạt động này?')) return; try { const updated = await assessmentApi.closeActivity(id); const index = activities.value.findIndex(item => item.id === id); if (index >= 0) activities.value[index] = updated } catch (cause) { error.value = errorMessage(cause) || 'Không đóng được hoạt động.' } }
watch(selectedClassId, value => { form.classId = value; load() }); onMounted(load)
</script>
